void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_num = regs->syscall_nr;

    if (syscall_num < 0 || syscall_num >= __NR_syscall_max)
        return;

    struct syscall_metadata *meta = &syscall_metadata_table[syscall_num];
    if (!meta || !meta->enable_perf)
        return;

    struct perf_event_header *header = perf_event_header_alloc();
    if (!header)
        return;

    header->type = PERF_RECORD_SYSCALL_EXIT;
    header->size = sizeof(*header) + sizeof(syscall_num) + sizeof(ret);

    char *buf = perf_event_header__raw_data(header);
    *(int *)buf = syscall_num;
    *(long *)(buf + sizeof(syscall_num)) = ret;

    perf_event_output(0, header, PERF_SAMPLE_RAW, 0, 0, buf, header->size);
}

void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_nr = regs->syscallno;

    if (syscall_nr < 0 || syscall_nr >= __NR_syscall_max)
        return;

    if (!is_perf_event_enabled(syscall_exit_event))
        return;

    struct syscall_metadata *metadata = get_syscall_metadata(syscall_nr);
    if (!metadata)
        return;

    if (!(metadata->flags & SYSCALL_EXIT_EVENT))
        return;

    struct trace_buffer *buffer = prepare_trace_buffer();
    if (!buffer)
        return;

    trace_record(buffer, metadata->id, regs, ret);
    submit_trace_buffer(buffer);
}

void syscall_exit_trace(void *ignore, struct pt_regs *regs, long ret) {
    int syscall_num = regs->syscall;

    if (syscall_num < 0 || syscall_num >= __NR_syscall_max)
        return;

    struct syscall_metadata *metadata = get_syscall_metadata(syscall_num);
    if (!metadata || !metadata->exit_event)
        return;

    char buffer[128];
    int len = 0;

    len += snprintf(buffer + len, sizeof(buffer) - len, "%d", syscall_num);
    len += snprintf(buffer + len, sizeof(buffer) - len, " %ld", ret);

    trace_submit(buffer, len);
}

void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret) {
    int syscall_num = regs->syscall;

    if (syscall_num < 0 || syscall_num >= __NR_syscall_max)
        return;

    struct syscall_metadata *metadata = get_syscall_metadata(syscall_num);
    if (!metadata || !metadata->enable_perf)
        return;

    if (!metadata->exit_event)
        return;

    char buffer[PERF_BUFFER_SIZE];
    int event_id = metadata->exit_event;

    buffer[0] = (char)syscall_num;
    *(long *)(buffer + 1) = ret;

    submit_perf_buffer(buffer, sizeof(char) + sizeof(long), event_id);
}

#include <linux/tracepoint.h>
#include <linux/errno.h>
