void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_num = regs->ax;
    struct syscall_metadata *metadata;

    if (syscall_num < 0 || syscall_num >= __NR_syscall_max)
        return;

    metadata = get_syscall_metadata(syscall_num);
    if (!metadata)
        return;

    if (!metadata->exit_event)
        return;

    struct trace_buffer *buf = prepare_trace_buffer();
    if (!buf)
        return;

    buf->syscall_num = syscall_num;
    buf->return_value = ret;
    submit_trace_buffer(buf);
}
